Add Reconcile(). Call it in OnInit after LoadState, at the top of Decide, and every 60 s from OnTimer:
void Reconcile()
  {
   if(InpMode != GO_AUTO) return;
   for(int i = PositionsTotal() - 1; i >= 0; i--)
     {
      ulong t = PositionGetTicket(i);
      if(t == 0 || t == g.real_ticket || PositionGetString(POSITION_SYMBOL) != _Symbol || PositionGetInteger(POSITION_MAGIC) != InpMagic) continue;
      if(g.real_ticket != 0 && PositionSelectByTicket(g.real_ticket)) { g_trade.PositionClose(t); continue; }   // extra leg
      PositionSelectByTicket(t);
      datetime dec = BucketUTC(ToUTC((datetime)PositionGetInteger(POSITION_TIME)));
      Bar4 b[]; int n = Build4H(b, dec); double atr = WilderATR(b, n, InpATRPeriod);
      g.real_ticket = t; g.real_side = (PositionGetInteger(POSITION_TYPE) == POSITION_TYPE_BUY) ? 1 : -1;
      g.real_fill = PositionGetDouble(POSITION_PRICE_OPEN);
      g.real_D = (atr > 0) ? InpStopATR * atr : MathAbs(g.real_fill - PositionGetDouble(POSITION_SL));
      g.real_deadline_utc = DeadlineUTC(dec, InpMaxDays);
      MqlRates r[]; int k = CopyRates(_Symbol, PERIOD_M1, (datetime)PositionGetInteger(POSITION_TIME), TimeCurrent(), r);
      g.real_best = g.real_fill;
      for(int j = 0; j < k; j++) g.real_best = (g.real_side > 0) ? MathMax(g.real_best, r[j].high) : MathMin(g.real_best, r[j].low + r[j].spread * _Point);
      DeletePendings();
      Journal("REAL_ADOPT", ToUTC(TimeTradeServer()), g.real_side, g.real_fill, 0, atr, 0, IntegerToString((long)t));
      Notify(StringFormat("GoldOrb : position #%I64u ouverte pendant un arret, reprise en charge (sortie max %s).", t, Clocks(g.real_deadline_utc)));
     }
  }
