void RealTimeExit()
  {
   if(InpMode == GO_ALERTS || !RealPositionSelected()) return;
   datetime now = ToUTC(TimeTradeServer());
   if(now < g.real_deadline_utc || TimeLocal() - g_tx_try < 15) return;
   g_tx_try = TimeLocal();
   if(g_trade.PositionClose(g.real_ticket) && g_trade.ResultRetcode() == TRADE_RETCODE_DONE)
     {
      Journal("REAL_CLOSE", now, g.real_side, g_trade.ResultPrice(), 0, 0, 0, "time");
      g.real_ticket = 0; g_tx_warn = false; SaveState();
     }
   else if(!g_tx_warn)
     {
      g_tx_warn = true;
      Notify(StringFormat("GoldOrb : FERMETURE AU TEMPS REFUSEE (%s). Nouvel essai toutes les 15 s. Fermez vous-meme la position #%I64u.", g_trade.ResultRetcodeDescription(), g.real_ticket));
     }
  }
